export default function () {
  const patients = [
    {
      name: "Angela Chiwaya",
      id: "OPQ5-WRT1",
      date: "05-Oct-2025, 09:45 AM",
      scan: "Chest X-ray",
      finding: "Pneumonia",
    },
    {
      name: "Chifundo Gama",
      id: "MV01-6TA0",
      date: "06-May-2025, 02:35 PM",
      scan: "CT Scan",
      finding: "Pneumonia",
    },
    {
      name: "Paul Chilewesa",
      id: "R003-FK8E",
      date: "08-May-2025, 02:35 PM",
      scan: "Chest X-ray",
      finding: "Pneumonia",
    },
  ];

  return (
    <div className="flex flex-col items-center justify-center p-6">
      <h1 className="text-xl font-semibold text-green-400 mb-4">MedVision AI Lab</h1>

      <div className="bg-gray-700 w-full max-w-md rounded-2xl p-6 shadow-lg space-y-4">
        <h2 className="font-semibold mb-2">Diagnostic History</h2>

        {patients.map((p, i) => (
          <div key={i} className="bg-gray-600 rounded-lg p-3 flex justify-between items-center">
            <div>
              <p className="font-semibold">{p.name}</p>
              <p className="text-sm">{p.id}</p>
              <p className="text-sm">{p.date}</p>
              <p className="text-sm">{p.scan}</p>
            </div>
            <div className="text-right">
              <p className="bg-gray-800 px-3 py-1 rounded-lg">{p.finding}</p>
              <a href="#" className="text-blue-400 text-sm hover:underline">Send to Radiologist</a>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
